CREATE_TRIGGER = """
CREATE FUNCTION sources_segment_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'sources_segment is append-only: % refused', TG_OP
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF (SELECT data_class FROM sources_document WHERE id = NEW.document_id)
            IS DISTINCT FROM 'demonstration' THEN
        RAISE EXCEPTION 'sources_segment holds only the text of a demonstration document'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF NEW.text IS NOT NFC NORMALIZED THEN
        RAISE EXCEPTION 'sources_segment text is held in NFC'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF NEW.text_sha256 <> encode(sha256(convert_to(NEW.text, 'UTF8')), 'hex') THEN
        RAISE EXCEPTION 'sources_segment hash does not match its text'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER sources_segment_protect
    BEFORE INSERT OR UPDATE OR DELETE ON sources_segment
    FOR EACH ROW EXECUTE FUNCTION sources_segment_guard();
"""

